+const app = document.querySelector('#app');
+const dialog = document.querySelector('#add-dialog');
+const form = document.querySelector('#add-form');
+const toast = document.querySelector('#toast');
+let books = [];
+let toastTimeout;
+
+const palettes = [
+  ['#d9a889', '#7e4338', '#f7e5d4'],
+  ['#83928b', '#344a45', '#dce4dc'],
+  ['#d9c579', '#786234', '#f5e9bd'],
+  ['#9a9dc0', '#474568', '#e4e3f0'],
+  ['#cf8d85', '#753c40', '#f3ddda'],
+  ['#a8b17c', '#4e5b3f', '#e6e9ce'],
+];
+
+function escapeHtml(value = '') {
+  return String(value).replace(/[&<>\"']/g, (character) => ({
+    '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;',
+  })[character]);
+}
+
+function coverFor(book, index = 0, large = false) {
+  const palette = palettes[index % palettes.length];
+  const initials = book.title.split(/\\s+/).slice(0, 2).map((word) => word[0]).join('').toUpperCase();
+  return "'`<div class="book-cover${large ? '"' book-cover-large' : ''}\" style=\"--cover:"'${palette[0]};--cover-dark:${palette[1]};--cover-light:${palette[2]}" aria-hidden="true"><span class="cover-rule"></span><span class="cover-initials">${escapeHtml(initials)}</span><span class="cover-bottom">A READING ROOM<br />EDITION</span></div>`;
+}
+
+function renderBookCard(book, index, finished = false) {
+  const notePreview = book.notes ? `<p class="book-note">“${escapeHtml(book.notes.slice(0, 100))}${book.notes.length > 100 ? '"'…' : ''}”</p>"'` : '"'';
+  return "'`<article class="book-card">
+    <a class="book-card-main" href="/books/${encodeURIComponent(book.id)}" data-route>
+      ${coverFor(book, index)}
+      <span class="book-info"><span class="book-title">${escapeHtml(book.title)}</span><span class="book-author">${escapeHtml(book.author)}</span>${notePreview}</span>
+      <span class="card-arrow" aria-hidden="true">↗</span>
+    </a>
+    ${finished ? `<span class="finished-label"><span>✓</span> Finished${book.finishedAt ? ` · ${new Date(book.finishedAt).toLocaleDateString(undefined, { month: '"'short', year: 'numeric' })}"'` : '"''}</span>"'` : `<button class="finish-button" data-finish="${escapeHtml(book.id)}">Mark as finished <span>→</span></button>`}
+  </article>`;
+}
+
+function sectionMarkup(title, count, items, finished = false) {
+  const empty = finished
+    ? '"'<div class=\"empty-inline\">Your finished books will find a home here.</div>'
+    : '<div class=\"empty-reading\"><div class=\"empty-icon\">⌁</div><h3>A fresh page.</h3><p>Every good reading list starts somewhere.<br />Add the book you’re spending time with.</p><button class=\"button button-outline\" data-open-form>+ Add your first book</button></div>';
+  return "'`<section class="shelf-section ${finished ? '"'finished-section' : ''}\"><div class=\"section-heading\"><div><p class=\"eyebrow\">"'${finished ? '"'THE LAST PAGE' : 'ON YOUR NIGHTSTAND'}</p><h2>"'${title}<span class="section-count">${count}</span></h2></div>${finished && count ? '"'<span class=\"section-aside\">Stories stay with us.</span>' : ''}</div>"'${items.length ? `<div class="book-list">${items.map((book, index) => renderBookCard(book, index + (finished ? 2 : 0), finished)).join('"'')}</div>"'` : empty}</section>`;
+}
+
+function renderShelf() {
+  const reading = books.filter((book) => book.status !== '"'finished');
+  const finished = books.filter((book) => book.status === 'finished');
+  app.innerHTML = "'`<section class="welcome">
+      <div class="welcome-copy"><p class="eyebrow"><span class="welcome-spark">✳</span> YOUR PERSONAL BOOKSHELF</p><h1>Stories in<br /><em>progress.</em></h1><p class="welcome-description">A quiet little place to keep the books you’re reading—and the ones that stay with you.</p></div>
+      <div class="welcome-art" aria-hidden="true"><div class="sun-disc"></div><div class="art-window"><span class="window-line window-line-one"></span><span class="window-line window-line-two"></span><span class="window-line window-line-three"></span><span class="window-leaf leaf-one"></span><span class="window-leaf leaf-two"></span><span class="window-leaf leaf-three"></span></div><div class="art-book book-one"></div><div class="art-book book-two"></div><div class="art-book book-three"></div><div class="art-table"></div><span class="art-caption">your next chapter awaits</span></div>
+      <div class="welcome-stats"><span><strong>${reading.length.toString().padStart(2, '"'0')}</strong> reading now</span><span class=\"stats-divider\"></span><span><strong>"'${finished.length.toString().padStart(2, '"'0')}</strong> read & remembered</span></div>
+    </section>
+    <div class=\"shelf-wrap\">"'${sectionMarkup('"'Currently reading', reading.length, reading)}"'${sectionMarkup('"'Finished', finished.length, finished, true)}</div>"'`;
+}
+
+function renderDetail(book) {
+  const index = books.findIndex((item) => item.id === book.id);
+  const finished = book.status === '"'finished';
+  app.innerHTML = "'`<div class="detail-page"><a class="back-link" href="/" data-route>← <span>Back to your shelf</span></a>
+    <article class="detail-card">${coverFor(book, index < 0 ? 0 : index, true)}<div class="detail-copy"><p class="eyebrow">${finished ? '"'A STORY COMPLETED' : 'CURRENTLY READING'}</p><h1>"'${escapeHtml(book.title)}</h1><p class="detail-author">by ${escapeHtml(book.author)}</p><div class="detail-rule"></div><p class="notes-label">MY NOTES</p><p class="detail-notes">${book.notes ? escapeHtml(book.notes).replace(/'"\\n/g, '<br />') : '<span class=\"notes-empty\">No notes just yet. The best thoughts often come along the way.</span>'}</p><div class=\"detail-actions\"><button class=\"button button-outline\" id=\"share-book\">↗ Share this book</button>"'${finished ? '"'<span class=\"finished-label detail-finished\"><span>✓</span> Finished reading</span>' : "'`<button class="button button-dark" data-finish="${escapeHtml(book.id)}">Mark as finished <span>→</span></button>`}</div></div></article>
+    <p class="detail-footnote">A good book leaves a little mark. <span>✳</span></p></div>`;
+}
+
+function showToast(message) {
+  toast.textContent = message;
+  toast.classList.add('"'toast-visible');
+  clearTimeout(toastTimeout);
+  toastTimeout = setTimeout(() => toast.classList.remove('toast-visible'), 2600);
+}
+
+async function loadShelf() {
+  const response = await fetch('/api/books');
+  if ("'!response.ok) throw new Error('"'Could not load your shelf.');
+  books = await response.json();
+}
+
+async function navigate(path, { replace = false } = {}) {
+  if (path "'!== location.pathname) {
+    history[replace ? '"'replaceState' : 'pushState']({}, '', path);
+  }
+  await renderRoute();
+  window.scrollTo({ top: 0, behavior: 'smooth' });
+}
+
+async function renderRoute() {
+  if (location.pathname.startsWith('/books/')) {
+    const id = decodeURIComponent(location.pathname.slice('/books/'.length));
+    try {
+      const response = await fetch("'`/api/books/${encodeURIComponent(id)}`);
+      if (!response.ok) throw new Error('"'That book could not be found.');
+      renderDetail(await response.json());
+    } catch {
+      app.innerHTML = '<div class=\"not-found\"><p class=\"eyebrow\">LOST BETWEEN THE PAGES</p><h1>This book isn’t on the shelf.</h1><a href=\"/\" class=\"back-link\" data-route>← <span>Back to your shelf</span></a></div>';
+    }
+    return;
+  }
+  try {
+    await loadShelf();
+    renderShelf();
+  } catch {
+    app.innerHTML = '<div class=\"not-found\"><p class=\"eyebrow\">A LITTLE PAUSE</p><h1>Your shelf couldn’t be opened.</h1><p>Try refreshing in a moment.</p></div>';
+  }
+}
+
+document.addEventListener('click', async (event) => {
+  const openButton = event.target.closest('[data-open-form]');
+  if (openButton) {
+    form.querySelector('.form-error').textContent = '';
+    dialog.showModal();
+    setTimeout(() => form.elements.title.focus(), 50);
+    return;
+  }
+  const closeButton = event.target.closest('.close-dialog');
+  if (closeButton) {
+    dialog.close();
+    return;
+  }
+  const routeLink = event.target.closest('a[data-route]');
+  if (routeLink && event.button === 0 && "'!event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey) {
+    event.preventDefault();
+    await navigate(routeLink.getAttribute('"'href'));
+    return;
+  }
+  const finishButton = event.target.closest('[data-finish]');
+  if (finishButton) {
+    finishButton.disabled = true;
+    try {
+      const response = await fetch("'`/api/books/${encodeURIComponent(finishButton.dataset.finish)}`, {
+        method: '"'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished' }),
+      });
+      if ("'!response.ok) throw new Error();
+      await loadShelf();
+      await renderRoute();
+      showToast('"'Tucked away with the finished stories.');
+    } catch {
+      finishButton.disabled = false;
+      showToast('Couldn’t update the book. Try again.');
+    }
+    return;
+  }
+  if (event.target.closest('#share-book')) {
+    const shareButton = event.target.closest('#share-book');
+    try {
+      await navigator.clipboard.writeText(location.href);
+      shareButton.textContent = '✓ Link copied';
+      setTimeout(() => { if (shareButton.isConnected) shareButton.innerHTML = '↗ Share this book'; }, 1800);
+    } catch {
+      showToast('Copy this page’s address to share the book.');
+    }
+  }
+});
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  const submitButton = form.querySelector('[type=\"submit\"]');
+  submitButton.disabled = true;
+  form.querySelector('.form-error').textContent = '';
+  const payload = Object.fromEntries(new FormData(form));
+  try {
+    const response = await fetch('/api/books', {
+      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload),
+    });
+    const result = await response.json();
+    if ("'!response.ok) throw new Error(result.error || '"'Could not add this book.');
+    form.reset();
+    dialog.close();
+    await navigate("'`/books/${encodeURIComponent(result.id)}`);
+    showToast('"'Added to your shelf. Happy reading.');
+  } catch (error) {
+    form.querySelector('.form-error').textContent = error.message || 'Could not add this book. Try again.';
+  } finally {
+    submitButton.disabled = false;
+  }
+});
+
+dialog.addEventListener('click', (event) => {
+  if (event.target === dialog) dialog.close();
+});
+
+window.addEventListener('popstate', renderRoute);
+renderRoute();
